/* ===== KACHEL-BIBLIOTHEK: Böden und Objekte für den Weltbau (Spiel und Editor) =====
   Boden-Stile (GR) ersetzen die Farbe und Struktur einer begehbaren Kachel.
   Objekte (OB) stehen oben drauf; "solid" blockiert den Weg.
   Eigene Kacheln: TILE_REG[id] = { id, n, cat, kind: "ground"|"obj", solid, draw(c, px, py, sd, x, y) }.
   draw malt in ein 32x32-Feld (px, py = obere linke Ecke); Objekte dürfen nach oben herausragen. */
/* Ebenen der Welt: GR = Boden-Stil, OB = Objekt (je Kachel eine Kennung oder null) */
const GR = new Array(WW * WH).fill(null), OB = new Array(WW * WH).fill(null);
const TILE_REG = {};
const TILE_CATS = { ground: [], obj: [] };
function regTile(t) { TILE_REG[t.id] = t; const l = TILE_CATS[t.kind]; if (!l.includes(t.cat)) l.push(t.cat); return t; }
function unregTile(id) { delete TILE_REG[id]; }

/* ----- kleine Zeichenhelfer (auch für eigene Snippets gedacht) ----- */
const TH = {
  shadow(c, px, py, w) { c.fillStyle = "rgba(10,20,30,.22)"; c.beginPath(); c.ellipse(px + 16, py + 28, w || 13, 4, 0, 0, 7); c.fill(); },
  blob(c, x, y, r, fill, lw, ry) { c.fillStyle = fill; c.strokeStyle = INK; c.lineWidth = lw == null ? 2 : lw; c.beginPath(); c.ellipse(x, y, r, ry || r, 0, 0, 7); c.fill(); if (c.lineWidth > 0) c.stroke(); },
  poly(c, pts, fill, lw) { c.fillStyle = fill; c.strokeStyle = INK; c.lineWidth = lw == null ? 2 : lw; c.beginPath(); pts.forEach((p, i) => i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])); c.closePath(); c.fill(); if (c.lineWidth > 0) c.stroke(); },
  rect(c, x, y, w, h, fill, lw) { c.fillStyle = fill; c.strokeStyle = INK; c.lineWidth = lw == null ? 2 : lw; c.fillRect(x, y, w, h); if (c.lineWidth > 0) c.strokeRect(x, y, w, h); },
  line(c, pts, col, lw) { c.strokeStyle = col; c.lineWidth = lw || 1.5; c.beginPath(); pts.forEach((p, i) => i ? c.lineTo(p[0], p[1]) : c.moveTo(p[0], p[1])); c.stroke(); },
  hi(c, x, y, w, h) { c.fillStyle = "rgba(255,255,255,.35)"; c.beginPath(); c.ellipse(x, y, w, h, -.5, 0, 7); c.fill(); },
  star(c, x, y, r, fill) { c.fillStyle = fill; c.beginPath(); c.moveTo(x, y - r); c.quadraticCurveTo(x, y, x + r * .8, y); c.quadraticCurveTo(x, y, x, y + r); c.quadraticCurveTo(x, y, x - r * .8, y); c.quadraticCurveTo(x, y, x, y - r); c.fill(); }
};
const _mix = (a, b, k) => mixHex(a, b, k);

/* ===== BÖDEN ===== */
// Strukturgeneratoren: (c, px, py, x, y, col, dens, col2)
const GTEX = {
  none() {},
  tufts(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.5; c.beginPath(); const n = Math.round(2 + 6 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const bx = px + 3 + hs(x, y, 90 + i) * 26, by = py + 8 + hs(x, y, 100 + i) * 22; c.moveTo(bx, by); c.lineTo(bx - 2.5, by - 7); c.moveTo(bx, by); c.lineTo(bx + .5, by - 9); c.moveTo(bx, by); c.lineTo(bx + 3, by - 6); } c.stroke(); },
  tall(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.6; c.beginPath(); const n = Math.round(5 + 8 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const bx = px + 2 + hs(x, y, 90 + i) * 28, by = py + 10 + hs(x, y, 100 + i) * 20, h = 9 + hs(x, y, 110 + i) * 8; c.moveTo(bx, by); c.quadraticCurveTo(bx + (hs(x, y, 120 + i) - .5) * 6, by - h * .6, bx + (hs(x, y, 130 + i) - .5) * 8, by - h); } c.stroke(); },
  speck(c, px, py, x, y, col, d) { c.fillStyle = col; const n = Math.round(3 + 12 * (d == null ? .5 : d)); for (let i = 0; i < n; i++) { c.beginPath(); c.arc(px + 2 + hs(x, y, 140 + i) * 28, py + 2 + hs(x, y, 150 + i) * 28, .9 + hs(x, y, 160 + i) * 1.1, 0, 7); c.fill(); } },
  flowers(c, px, py, x, y, col, d, col2) { GTEX.tufts(c, px, py, x, y, col2 || "rgba(40,100,50,.55)", .3); const cs = Array.isArray(col) ? col : [col]; const n = Math.round(2 + 5 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const fx = px + 4 + hs(x, y, 170 + i) * 24, fy = py + 6 + hs(x, y, 180 + i) * 22; c.fillStyle = cs[(hs(x, y, 190 + i) * cs.length) | 0]; c.strokeStyle = INK; c.lineWidth = 1; c.beginPath(); c.arc(fx, fy, 2.7, 0, 7); c.fill(); c.stroke(); c.fillStyle = "#f6d24a"; c.beginPath(); c.arc(fx, fy, .9, 0, 7); c.fill(); } },
  clover(c, px, py, x, y, col, d) { c.fillStyle = col; const n = Math.round(2 + 5 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const cx = px + 4 + hs(x, y, 200 + i) * 24, cy = py + 5 + hs(x, y, 210 + i) * 22; for (let k = 0; k < 3; k++) { c.beginPath(); c.arc(cx + Math.cos(k * 2.1) * 2.2, cy + Math.sin(k * 2.1) * 2.2, 1.9, 0, 7); c.fill(); } } },
  leaves(c, px, py, x, y, col, d, col2) { const cs = [col, col2 || col]; const n = Math.round(3 + 8 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { c.fillStyle = cs[i % 2]; c.strokeStyle = "rgba(60,40,20,.5)"; c.lineWidth = 1; c.beginPath(); c.ellipse(px + 3 + hs(x, y, 220 + i) * 26, py + 3 + hs(x, y, 230 + i) * 26, 3.4, 1.8, hs(x, y, 240 + i) * 3, 0, 7); c.fill(); c.stroke(); } },
  needles(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.1; c.beginPath(); const n = Math.round(8 + 14 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const bx = px + 2 + hs(x, y, 250 + i) * 28, by = py + 2 + hs(x, y, 260 + i) * 28, a = hs(x, y, 270 + i) * 3.14; c.moveTo(bx, by); c.lineTo(bx + Math.cos(a) * 5, by + Math.sin(a) * 5); } c.stroke(); },
  cobble(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 1.4; c.fillStyle = col2 || "rgba(255,255,255,.08)"; const o = (x + y) & 1 ? 0 : 8; for (let r = 0; r < 3; r++) for (let k = 0; k < 3; k++) { const sx = px + ((k * 11 + (r & 1 ? 6 : 0) + o) % 33) - 3, sy = py + 1 + r * 10.5; c.beginPath(); c.roundRect ? c.roundRect(sx, sy, 10, 9, 3) : c.rect(sx, sy, 10, 9); c.fill(); c.stroke(); } },
  round(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 1.3; c.fillStyle = col2 || "rgba(255,255,255,.1)"; for (let r = 0; r < 3; r++) for (let k = 0; k < 3; k++) { const sx = px + 5.5 + k * 10.5 + (r & 1 ? 4 : -1) + (hs(x, y, 280 + r * 3 + k) - .5) * 2, sy = py + 5.5 + r * 10.5; c.beginPath(); c.arc(sx, sy, 4.4, 0, 7); c.fill(); c.stroke(); } },
  slabs(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 1.6; c.beginPath(); c.moveTo(px, py + 16); c.lineTo(px + 32, py + 16); c.moveTo(px + 16, py); c.lineTo(px + 16, py + 16); c.moveTo(px + 9 + (hs(x, y, 290) * 6 | 0), py + 16); c.lineTo(px + 9 + (hs(x, y, 290) * 6 | 0), py + 32); c.stroke(); c.fillStyle = col2 || "rgba(255,255,255,.1)"; c.fillRect(px + 2, py + 2, 12, 5); },
  bricks(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 1.5; c.beginPath(); for (let r = 0; r < 4; r++) { const yy = py + r * 8; c.moveTo(px, yy); c.lineTo(px + 32, yy); const off = r & 1 ? 8 : 0; for (let k = 0; k < 3; k++) { const xx = px + off + k * 16; if (xx > px && xx < px + 32) { c.moveTo(xx, yy); c.lineTo(xx, yy + 8); } } } c.stroke(); },
  planks(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 1.6; c.beginPath(); for (let r = 1; r < 4; r++) { c.moveTo(px, py + r * 8); c.lineTo(px + 32, py + r * 8); } c.stroke(); c.lineWidth = 1; c.globalAlpha = .6; c.beginPath(); for (let r = 0; r < 4; r++) { const sx = px + 4 + hs(x, y, 300 + r) * 22; c.moveTo(sx, py + r * 8 + 4); c.lineTo(sx + 7, py + r * 8 + 4); } c.stroke(); c.globalAlpha = 1; c.fillStyle = col2 || col; for (let r = 0; r < 4; r++) { c.beginPath(); c.arc(px + 3, py + r * 8 + 4, .9, 0, 7); c.arc(px + 29, py + r * 8 + 4, .9, 0, 7); c.fill(); } },
  planksV(c, px, py, x, y, col, d, col2) { c.save(); c.translate(px + 16, py + 16); c.rotate(Math.PI / 2); c.translate(-16, -16); GTEX.planks(c, 0, 0, x, y, col, d, col2); c.restore(); },
  furrows(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 2; c.beginPath(); for (let r = 0; r < 4; r++) { c.moveTo(px, py + 4 + r * 8); c.quadraticCurveTo(px + 8, py + 2 + r * 8, px + 16, py + 4 + r * 8); c.quadraticCurveTo(px + 24, py + 6 + r * 8, px + 32, py + 4 + r * 8); } c.stroke(); },
  waves(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.5; c.lineCap = "round"; const n = Math.round(1 + 2 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const cx = px + 2 + hs(x, y, 310 + i) * 12, cy = py + 7 + hs(x, y, 320 + i) * 18; c.beginPath(); c.moveTo(cx, cy); c.quadraticCurveTo(cx + 5, cy - 4, cx + 10, cy); c.quadraticCurveTo(cx + 15, cy + 4, cx + 20, cy); c.stroke(); } },
  cracks(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.3; if (hs(x, y, 330) < (d == null ? .5 : d)) { const cx = px + 5 + hs(x, y, 331) * 18, cy = py + 6 + hs(x, y, 332) * 18; c.beginPath(); c.moveTo(cx, cy); c.lineTo(cx + 5, cy + 3); c.lineTo(cx + 4, cy + 8); c.lineTo(cx + 10, cy + 10); c.stroke(); } },
  glow(c, px, py, x, y, col, d) { const n = Math.round(1 + 3 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) { const gx = px + 4 + hs(x, y, 340 + i) * 24, gy = py + 4 + hs(x, y, 350 + i) * 24, g = c.createRadialGradient(gx, gy, 0, gx, gy, 7); g.addColorStop(0, col); g.addColorStop(1, "rgba(255,255,255,0)"); c.fillStyle = g; c.beginPath(); c.arc(gx, gy, 7, 0, 7); c.fill(); } },
  sparkle(c, px, py, x, y, col, d) { const n = Math.round(1 + 3 * (d == null ? .6 : d)); for (let i = 0; i < n; i++) TH.star(c, px + 4 + hs(x, y, 360 + i) * 24, py + 4 + hs(x, y, 370 + i) * 24, 1.6 + hs(x, y, 380 + i) * 1.6, col); },
  runes(c, px, py, x, y, col) { c.strokeStyle = col; c.lineWidth = 1.5; c.strokeRect(px + 6, py + 6, 20, 20); if (hs(x, y, 390) < .6) { c.beginPath(); const k = (hs(x, y, 391) * 3) | 0; if (k === 0) { c.moveTo(px + 12, py + 10); c.lineTo(px + 12, py + 22); c.moveTo(px + 12, py + 14); c.lineTo(px + 20, py + 18); } else if (k === 1) { c.moveTo(px + 11, py + 22); c.lineTo(px + 16, py + 10); c.lineTo(px + 21, py + 22); c.moveTo(px + 13, py + 18); c.lineTo(px + 19, py + 18); } else { c.arc(px + 16, py + 16, 5, 0, 7); c.moveTo(px + 16, py + 9); c.lineTo(px + 16, py + 23); } c.stroke(); } },
  mosaic(c, px, py, x, y, col, d) { const cs = Array.isArray(col) ? col : [col]; for (let r = 0; r < 4; r++) for (let k = 0; k < 4; k++) { c.fillStyle = cs[(hs(x * 4 + k, y * 4 + r, 400) * cs.length) | 0]; c.globalAlpha = .55; c.fillRect(px + k * 8 + 1, py + r * 8 + 1, 6, 6); } c.globalAlpha = 1; },
  carpet(c, px, py, x, y, col, d, col2) { c.strokeStyle = col; c.lineWidth = 2; c.strokeRect(px + 3, py + 3, 26, 26); c.strokeStyle = col2 || col; c.lineWidth = 1; c.strokeRect(px + 7, py + 7, 18, 18); c.fillStyle = col2 || col; c.beginPath(); c.moveTo(px + 16, py + 11); c.lineTo(px + 21, py + 16); c.lineTo(px + 16, py + 21); c.lineTo(px + 11, py + 16); c.closePath(); c.fill(); },
  straw(c, px, py, x, y, col, d) { c.strokeStyle = col; c.lineWidth = 1.3; c.beginPath(); for (let i = 0; i < 14; i++) { const bx = px + hs(x, y, 410 + i) * 30, by = py + 2 + hs(x, y, 420 + i) * 28, a = (hs(x, y, 430 + i) - .5) * 1.6; c.moveTo(bx, by); c.lineTo(bx + Math.cos(a) * 7, by + Math.sin(a) * 7); } c.stroke(); },
  drift(c, px, py, x, y, col) { c.strokeStyle = col; c.lineWidth = 1.5; c.beginPath(); const cy = py + 8 + hs(x, y, 440) * 14; c.moveTo(px + 2, cy); c.quadraticCurveTo(px + 12, cy - 5, px + 22, cy); c.stroke(); TH.star(c, px + 6 + hs(x, y, 441) * 20, py + 6 + hs(x, y, 442) * 20, 1.8, "rgba(255,255,255,.9)"); },
  bubbles(c, px, py, x, y, col) { c.strokeStyle = col; c.lineWidth = 1; for (let i = 0; i < 2; i++) { c.beginPath(); c.arc(px + 6 + hs(x, y, 450 + i) * 20, py + 6 + hs(x, y, 455 + i) * 20, 2 + i, 0, 7); c.stroke(); } },
  grid(c, px, py, x, y, col) { c.strokeStyle = col; c.lineWidth = 1; c.beginPath(); c.moveTo(px + 16, py); c.lineTo(px + 16, py + 32); c.moveTo(px, py + 16); c.lineTo(px + 32, py + 16); c.stroke(); }
};
