function groundColor(def, x, y) { const lf = .5 + .5 * Math.sin(x * .21 + Math.sin(y * .17) * 1.8) * Math.cos(y * .19 + x * .07); return mixHex(def.col, def.col2 || def.col, Math.min(1, hs(x, y, 1) * 0.5 + lf * 0.5)); }
function groundTex(c, def, px, py, x, y) {
  if (def.draw) { def.draw(c, px, py, x * 7 + y, x, y); return; }
  if (def.img) { if (def.img.complete && def.img.naturalWidth) c.drawImage(def.img, px, py, 32, 32); return; }
  const f = GTEX[def.tex] || GTEX.none; f(c, px, py, x, y, def.tcol, def.dens, def.tcol2);
}

