// --- Bäume ---
function tree(c, px, py, s, crown, crown2, trunk, r) {
  r = r || 15; TH.shadow(c, px, py, 12);
  TH.rect(c, px + 13.5, py + 14, 5, 15, trunk, 2);
  c.fillStyle = "rgba(0,0,0,.15)"; c.fillRect(px + 16, py + 15, 2, 13);
  const cx = px + 16, cy = py - 2; c.lineJoin = "round";
  [[-9, 5, r * .62], [9, 5, r * .62], [0, -4, r * .8]].forEach((p, i) => TH.blob(c, cx + p[0], cy + p[1] + 6, p[2], i === 2 ? crown : crown2, 2.2));
  TH.blob(c, cx, cy + 4, r * .55, crown, 0); TH.hi(c, cx - 5, cy - 4, 5, 3);
}
