const crystalC = (id, n, a, b, dk) => defO(id, n, "Kristalle", true, (c, px, py) => { TH.shadow(c, px, py, 13); [[8, 30, 5, 17, b], [16, 31, 6, 26, a], [24, 30, 5, 15, b]].forEach(s => { const x = px + s[0], y = py + s[1], w = s[2], h = s[3]; TH.poly(c, [[x - w, y], [x - w * .8, y - h * .65], [x, y - h - 4], [x + w * .8, y - h * .6], [x + w, y]], s[4], 2); c.fillStyle = "rgba(255,255,255,.55)"; c.beginPath(); c.moveTo(x - w * .5, y - 2); c.lineTo(x - w * .45, y - h * .6); c.lineTo(x - 1, y - h); c.lineTo(x - 1, y - 2); c.fill(); c.strokeStyle = dk; c.lineWidth = 1; c.beginPath(); c.moveTo(x + w * .3, y - 2); c.lineTo(x + w * .3, y - h * .5); c.stroke(); }); });
