const glowShroom = (id, n, cap, glow) => defO(id, n, "Pilze & Moos", false, (c, px, py) => { const g = c.createRadialGradient(px + 16, py + 18, 0, px + 16, py + 18, 17); g.addColorStop(0, glow); g.addColorStop(1, "rgba(255,255,255,0)"); c.fillStyle = g; c.beginPath(); c.arc(px + 16, py + 18, 17, 0, 7); c.fill(); [[10, 8, 5], [18, 13, 7], [25, 7, 4.4]].forEach(p => { TH.rect(c, px + p[0] - 1.6, py + 30 - p[1], 3.2, p[1], "#f0e8f6", 1.6); TH.blob(c, px + p[0], py + 30 - p[1], p[2], cap, 1.8, p[2] * .7); c.fillStyle = "rgba(255,255,255,.7)"; c.beginPath(); c.arc(px + p[0] - p[2] * .3, py + 28 - p[1] - p[2] * .2, 1.1, 0, 7); c.fill(); }); });
