defO("o_runenstein", "Runenstein", "Höhle", true, (c, px, py) => { TH.shadow(c, px, py, 10); TH.poly(c, [[px + 7, py + 28], [px + 8, py + 8], [px + 14, py + 3], [px + 22, py + 5], [px + 25, py + 28]], "#8c8aa8", 2.2); c.strokeStyle = "#9fe8ff"; c.lineWidth = 1.8; c.beginPath(); c.moveTo(px + 13, py + 22); c.lineTo(px + 16, py + 10); c.lineTo(px + 20, py + 22); c.moveTo(px + 13.5, py + 17); c.lineTo(px + 19, py + 17); c.stroke(); });
