defO("o_fledermaus", "Fledermaus", "Höhle", false, (c, px, py) => { TH.poly(c, [[px + 16, py + 6], [px + 6, py + 2], [px + 9, py + 8], [px + 12, py + 7], [px + 16, py + 12], [px + 20, py + 7], [px + 23, py + 8], [px + 26, py + 2]], "#4a3a5a", 1.6); TH.blob(c, px + 16, py + 9, 3, "#4a3a5a", 1.4); c.fillStyle = "#ffd0d0"; c.fillRect(px + 14.4, py + 8.4, 1.2, 1.2); c.fillRect(px + 16.6, py + 8.4, 1.2, 1.2); });
